rules.expr:
sum(count_over_time(
  {service="backend"} |= "printenv" |= "[ATTACK]" [2m]
)) > 0

sum(count_over_time(
  {service=~"backend|frontend"}
  |~ "(?i)(wget http|wget -|curl http[^s]|curl -o |nc -|netcat|/bin/bash -i|/bin/sh -i)" [2m]
)) > 0

sum(count_over_time(
  {service="backend"} |~ "suspicious_outbound" [2m]
)) > 0

sum(count_over_time(
  {service="frontend"} |~ "(?i)(\\.\\.\\/|\\.\\.\\\\|/etc/passwd|\\.env|/\\.git/)" [2m]
)) > 0

sum(count_over_time(
  {service="backend"} |~ "container_escape_attempt" [2m]
)) > 0

sum by (dst_ip, dst_port) (
  sum_over_time(
    {log_type="network", event_type="connection", src_service="backend", dst_service!~"db|minio|frontend"} | json | __error__="" | (dst_ip!="10.210.0.30" or dst_port!=8080) | bytes_sent!="" | unwrap bytes_sent [5m]
  )
) > 1048576

sum by (dst_ip, dst_port) (
  count_over_time(
    {log_type="network", event_type="connection_threshold", src_service="backend", dst_service!~"db|minio|frontend"} | json | __error__="" | (dst_ip!="10.210.0.30" or dst_port!=8080) [5m]
  )
) > 0

sum(count_over_time(
  {log_format="json", service="frontend"} | json | status >= 500 | __error__="" [1m]
)) > 10

sum(count_over_time(
  {log_format="json", service="frontend"} | json | status >= 400 and status < 500 | __error__="" [1m]
)) > 50

sum(count_over_time(
  {service="db"} |= "authentication failed" [2m]
)) > 3

sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) > 0.5 and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-frontend"}

sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) > 0.5 and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-backend"}

max by (name) (
  sum_over_time(
    (
      (
        last_over_time(aiops_docker_container_restarts_total{instance="pipeline:8000", job="pipeline-metadata", name="leafy-backend"}[10m])
        - last_over_time(aiops_docker_container_restarts_total{instance="pipeline:8000", job="pipeline-metadata", name="leafy-backend"}[10m] offset 5s)
      ) >= 0
      or
      (
        last_over_time(aiops_docker_container_restarts_total{instance="pipeline:8000", job="pipeline-metadata", name="leafy-backend"}[10m])
        < last_over_time(aiops_docker_container_restarts_total{instance="pipeline:8000", job="pipeline-metadata", name="leafy-backend"}[10m] offset 5s)
      ) + 0
    )[10m:5s]
  )
) >= 2 or max by (name) (
  changes(aiops_docker_container_started_at_seconds{instance="pipeline:8000", job="pipeline-metadata", name="leafy-backend"}[10m])
) >= 2

sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) > 0.5 and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-db"}

sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) > 0.5 and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-minio"}

max by (name) (
  (
    container_memory_working_set_bytes{id=~"/docker/.+", instance="cadvisor:8080", job="cadvisor"}
    / (container_spec_memory_limit_bytes{id=~"/docker/.+", instance="cadvisor:8080", job="cadvisor"} > 0)
  ) * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) > 0.85

(
  sum by (name) (
    rate(container_network_receive_bytes_total{interface!="lo", id=~"/docker/.+", name!="", name=~"leafy-frontend|leafy-backend|leafy-db|leafy-minio", instance="cadvisor:8080", job="cadvisor"}[1m])
  ) > 1e7
) or (
  (
    sum without (interface) (
      rate(container_network_receive_bytes_total{interface!="lo", id="/", instance="cadvisor:8080", job="cadvisor"}[1m])
    ) > 1e7
  )
  unless on ()
  (count(container_network_receive_bytes_total{id=~"/docker/.+", instance="cadvisor:8080", job="cadvisor"}) > 0)
)
